contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Call sequence: record owner's balance, call burn, record owner's balance again.
    // The property: owner's balance decreases by exactly _value after burn.
    function run(uint256 _value) public {
        address owner = c.owner();
        uint256 before = c.balanceOf(owner);
        // precondition: owner must have at least _value to allow burn to succeed
        require(before >= _value);
        // perform the state-changing call
        c.burn(_value);
        uint256 after = c.balanceOf(owner);
        assert(after + _value == before);
    }

    // allow receiving ETH just in case
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // caller must be the owner for onlyOwner modifier to allow the burn call
        require(msg.sender == c.owner());
        // read balances before
        uint256 beforeOwner = c.balanceOf(c.owner());
        uint256 beforeTotal = c.totalSupply();
        // perform burn as owner
        c.burn(v);
        // read after
        uint256 afterOwner = c.balanceOf(c.owner());
        uint256 afterTotal = c.totalSupply();
        // General rule: owner's balance decreased by v and totalSupply decreased by v
        assert(beforeOwner - afterOwner == v && beforeTotal - afterTotal == v);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address other) public payable {
        require(other != address(0));
        // call burn from this contract's msg.sender (the caller of run) is forwarded by c because onlyOwner restricts it;
        // to trigger the function we must be the owner of c. The test assumes the caller of run is the owner of c.
        // Call burn with value 1 (any positive number) to change state.
        c.burn(1);
        // Assert that totalSupply is not greater than owner's balance + other balance + 0 (i.e., at least owner's balance is <= totalSupply).
        // We can only observe balances via public getters: owner(), balanceOf(address), totalSupply().
        address ownerAddr = c.owner();
        uint256 ownerBal = c.balanceOf(ownerAddr);
        uint256 otherBal = c.balanceOf(other);
        uint256 ts = c.totalSupply();
        // General invariant: totalSupply is at least owner's balance (true in original; broken in mutant where burn subtracts owner's balance but emits msg.sender)
        assert(ts >= ownerBal);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // require caller is owner so onlyOwner passes when calling burn
        require(msg.sender == c.owner(), "caller must be owner");
        // capture owner address
        address owner = c.owner();
        // call burn as owner
        c.burn(v);
        // observe totalSupply and owner's balance via public getters
        uint256 ts = c.totalSupply();
        uint256 balOwner = c.balanceOf(owner);
        // General rule: totalSupply is at least owner's balance
        assert(ts >= balOwner);
    }
    receive() external payable { }
