contract InvMutTest {
    C c;
    uint256 priorTotal;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // require caller is owner to satisfy onlyOwner in both versions
        // We require that msg.sender equals the owner stored in c by reading c.owner().
        // However, run is executed by any external caller; enforce that the caller is the owner by checking equality.
        require(c.owner() == msg.sender, "caller must be owner");
        // record prior totalSupply
        priorTotal = c.totalSupply();
        // perform the state-changing call that differs between P and M
        c.burn(v);
        // After a successful burn by the owner, totalSupply must have decreased by exactly v
        // i.e., new totalSupply == priorTotal - v. This holds for the original but is violated by the mutant.
        assert(c.totalSupply() == priorTotal - v);
    }
    receive() external payable { }
}

