pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // Fuzz parameter: an amount to burn and an address that will act as msg.sender (the owner must be that address)
    function testFuzz_property(uint256 burnAmount, address caller) public {
        // Keep domain wide but sensible: ensure caller is not zero and amount fits in balances
        vm.assume(caller != address(0));
        // The deployment setUp made msg.sender the owner (test contract), but constructor used msg.sender at deploy time.
        // We need the owner to be an EOA we can control via vm.prank: that's the test contract address (address(this)).
        // Ensure caller is the owner by using the test contract as caller (address(this)). We still fuzz burnAmount.
        // Fund the owner with a sufficient balance so burn can succeed for a wide range of burnAmount values.

        // Give the contract owner (which is address(this) at deployment) a large balance in the token by minting.
        // c.mintToken is onlyOwner, and address(this) is owner so allowed.
        uint256 seedMint = type(uint256).max / 4; // large mint to avoid overflow
        // bound burnAmount to [0, seedMint]
        uint256 amt = burnAmount % (seedMint + 1);

        // mint to owner (address(this)) and also optionally mint to another account to create imbalance cases
        c.mintToken(address(this), seedMint);
        // record totalSupply before burn
        uint256 beforeTotal = c.totalSupply();
        // perform burn as owner
        vm.prank(address(this));
        bool ok;
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful call, the correct contract should have decreased totalSupply by exactly amt.
        // We assert that: either the call reverted (ok == false) or totalSupply == beforeTotal - amt.
        // This single assertion holds for the reference for all valid inputs, but the mutant will sometimes
        // produce a different totalSupply because it subtracts from owner balance rather than msg.sender's balance.
        if (ok) {
            assertTrue(c.totalSupply() == beforeTotal - amt);
        } else {
            // If call reverted, then totalSupply unchanged for reference; express that as the same relation
            assertTrue(c.totalSupply() == beforeTotal);
        }
    }
}

