pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzz: amount to burn and whether the caller is the owner or a forwarding helper
    function testFuzz_property(uint256 amt, bool useHelper) public {
        // Keep amt in a reasonable range (wide) to avoid underflow in setup math
        amt = bound(amt, 0, type(uint256).max / 2);

        // Prepare two actors
        address owner = address(this); // deployer is owner because setUp used msg.sender
        address other = address(0xABCD);

        // Give balances: mint some tokens to other and to owner using mintToken (owner only)
        // owner is this contract (test), so call c.mintToken
        // Ensure we have enough ether/privilege — this contract is owner, so call directly
        c.mintToken(other, amt + 1); // give other at least amt+1
        c.mintToken(owner, amt + 1); // give owner at least amt+1

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeCallerBal;

        if (!useHelper) {
            // Owner calls burn directly
            beforeCallerBal = c.balanceOf(owner);
            bool ok;
            try c.burn(amt) {
                ok = true;
            } catch {
                ok = false;
            }
            // after call, totalSupply should have decreased by amt if call succeeded
            uint256 afterTotal = c.totalSupply();
            if (ok) {
                assertTrue(afterTotal + amt == beforeTotal);
            } else {
                // If the call reverted, totalSupply unchanged
                assertTrue(afterTotal == beforeTotal);
            }
            return;
        } else {
            // Use a helper that forwards calls (so msg.sender inside C is the helper)
            Forwarder f = new Forwarder(address(c));
            // fund helper so it can forward if needed
            vm.deal(address(f), 0);

            // Ensure helper has been granted tokens? mint to helper via owner
            c.mintToken(address(f), amt + 1);

            // record before
            beforeCallerBal = c.balanceOf(address(f));

            // have the helper call burn(amt) (msg.sender inside C will be helper)
            bool ok = f.forwardBurn(amt);

            uint256 afterTotal = c.totalSupply();
            uint256 afterCallerBal = c.balanceOf(address(f));

            // The general invariant we assert: if the burn call succeeded, totalSupply decrease equals the decrease of msg.sender's balance
            if (ok) {
                assertTrue(beforeCallerBal == afterCallerBal + amt && afterTotal + amt == beforeTotal);
            } else {
                // if helper's call reverted, nothing changed
                assertTrue(beforeCallerBal == afterCallerBal && afterTotal == beforeTotal);
            }
        }
    }
}

// helper that simply forwards calls so that msg.sender in C is this helper
contract Forwarder {
    address c;
    constructor(address _c) { c = _c; }
    function forwardBurn(uint256 amt) external returns (bool ok) {
        try C(c).burn(amt) {
            return true;
        } catch {
            return false;
        }
    }
}

