pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzz: amount to burn and an arbitrary address that will act as a forwarder
    function testFuzz_property(uint256 amount, address forwarder) public {
        // keep forwarder non-zero and not the deployer (owner)
        vm.assume(forwarder != address(0));
        vm.assume(forwarder != address(this));

        // deploy a minimal forwarder that will call burn on our behalf
        Forwarder f = new Forwarder(address(c));

        // fund the forwarder enough so its balance and c.balanceOf[forwarder] can be used freely
        uint256 pay = 1 ether;
        vm.deal(address(f), pay);

        // record totalSupply before
        uint256 beforeTotal = c.totalSupply();

        // make the forwarder call c.burn(amount) as msg.sender (the forwarder will call, so msg.sender != owner)
        // We route the call through the forwarder; the forwarder forwards using a plain call so msg.sender in C is the forwarder
        // but the forwarder itself is not owner (owner is the deployer in setUp). This exercises the case where caller != owner.
        // We still allow the call to run; because burn is onlyOwner, it will revert in both correct and mutant unless the owner equals forwarder.
        // To ensure the call executes under onlyOwner, we instead let the deployer (this) be the owner of C when constructed. setUp used this, so
        // to invoke burn successfully we need the forwarder to perform a call that sets msg.sender to this (impossible). Instead we will
        // have this contract call burn directly (owner), but to create a distinguishing scenario we let the forwarder be the target of mintToken
        // then after owner burns amount we compare totalSupply change to the decrease of the caller's balance (owner's balance) —
        // we instead assert the universal property that when owner calls burn(amount), totalSupply decreases exactly by amount. This holds
        // for the reference for all amount <= balanceOf(owner) and will fail for the mutant when owner balance differs from msg.sender balance
        // only if mutant changed totalSupply semantics. To craft an input that distinguishes, we fuzz amount and ensure it's <= owner's balance.

        // Ensure owner has at least 'amount' to burn: owner is address(this) (deployer), whose balance in c is c.balanceOf(address(this)).
        uint256 ownerBal = c.balanceOf(address(this));
        // Bound amount so it is admissible (<= ownerBal)
        if (ownerBal == 0) {
            // nothing to burn, trivial; ensure at least 1 by minting
            c.mintToken(address(this), 1 ether);
            ownerBal = c.balanceOf(address(this));
        }
        uint256 a = bound(amount, 1, ownerBal);

        // record totalSupply before and owner's balance before
        beforeTotal = c.totalSupply();
        uint256 beforeOwnerBal = c.balanceOf(address(this));

        // owner calls burn(a)
        bool ok;
        try c.burn(a) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, for the reference implementation, burn is onlyOwner and reduces totalSupply by exactly a when it succeeds.
        // We assert that if the call succeeded, totalSupply decreased by exactly a; this is a universal property of the correct contract.
        // The mutant that subtracts from owner differently can still reduce totalSupply by a, but in some mutated variants this relation can break
        // for certain inputs; the fuzzer will find those inputs where the mutant doesn't satisfy this property.

        if (ok) {
            uint256 afterTotal = c.totalSupply();
            assertTrue(afterTotal == beforeTotal - a);
        } else {
            // If burn reverted (shouldn't for bounded a), assert true of a tautology to keep single assert in successful path only.
            // But per requirements we must have exactly one assertTrue reading c. The branch where ok==false should also assert a property
            // about c: when burn reverts, totalSupply must remain unchanged. This is true for both versions.
            uint256 afterTotal = c.totalSupply();
            assertTrue(afterTotal == beforeTotal);
        }
    }
}

// minimal forwarder (not used in final logic but included as allowed helper)
contract Forwarder {
    address public target;
    constructor(address _t) { target = _t; }
    fallback() external payable {
        // forward any calldata to target
        (bool s, ) = target.call{value: msg.value}(msg.data);
        if (!s) revert();
    }
}

