pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzz: amount to burn and initial ether for forwarder (unused but demonstrates fuzz params exist)
    function testFuzz_property(uint256 amount, uint256 dummy) public {
        // Keep amount in a reasonable wide range but not extremely large to avoid overflow in balance ops
        amount = bound(amount, 0, type(uint256).max / 2);
        // Deploy a forwarder that will call c.burn(amount) so msg.sender inside C is the forwarder
        Forwarder f = new Forwarder(address(c));

        // Fund the forwarder with tokens by minting to it using the contract owner (setUp deployer is owner)
        // owner currently (setUp) has totalSupply = 0 * 10**decimals == 0, so mint some tokens to forwarder
        // Use vm.prank to act as owner (the deploying address) to call mintToken
        address owner = address(this);
        // Make sure owner has the authority: the deploying address is the owner by constructor
        // Mint a large amount to both owner and forwarder so balances cover amount
        uint256 seed = bound(dummy, 1, 1e18);
        c.mintToken(address(f), amount + seed);
        c.mintToken(owner, amount + seed);

        // Record totalSupply and forwarder balance before
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeFwdBal = c.balanceOf(address(f));

        // Forwarder calls burn(amount) on C so msg.sender inside C == address(f)
        bool ok;
        try f.callBurn(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Record after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterFwdBal = c.balanceOf(address(f));

        // GENERAL RULE (single assertion): For the correct contract, if the forwarder successfully invoked burn(amount),
        // then totalSupply decreases by exactly the amount burned and that decrease equals the forwarder's balance decrease.
        // We assert this relation using c's public getters. The mutant that subtracts from owner instead of msg.sender
        // will violate it for some inputs (e.g., when owner balance != forwarder balance).
        // We express the rule universally: if the call succeeded (ok==true) then beforeTotal - afterTotal == beforeFwdBal - afterFwdBal
        assertTrue(!ok || (beforeTotal - afterTotal == beforeFwdBal - afterFwdBal));
    }
}

// Minimal forwarder that simply calls burn on C; this makes msg.sender inside C be the forwarder's address
contract Forwarder {
    C target;
    constructor(address _t) { target = C(_t); }
    function callBurn(uint256 v) external {
        target.burn(v);
    }
}

