pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // We fuzz the amount to burn and use a forwarder contract so that inside C, msg.sender is the forwarder,
    // which lets us observe the difference between debiting msg.sender vs owner.
    function testFuzz_property(uint256 amount) public {
        // keep amount reasonably bounded so it doesn't overflow arithmetic in the contract
        amount = bound(amount, 0, type(uint256).max / 2);

        // Deploy a forwarder that will call c.burn(amount) so that msg.sender != tx.origin and msg.sender != owner
        Forwarder f = new Forwarder(address(c));

        // Ensure forwarder has no special balance in C (C holds balances mapping only for its owner initially)
        // Mint some tokens to forwarder and to owner so calls are admissible when needed
        // Owner is the deployer (this contract deployed C in setUp), so this contract is owner.
        // Use vm.prank to act as owner for minting: owner == address(this) at construction
        vm.prank(address(this));
        c.mintToken(address(f), amount);

        // record totalSupply before
        uint256 before = c.totalSupply();

        // Have the forwarder call burn(amount) (the forwarder will call C.burn(amount) where msg.sender==address(f))
        // Since onlyOwner modifier restricts burn to owner (address(this) was owner), calling burn via forwarder
        // will only succeed if the forwarder somehow is allowed; to simulate a forwarding scenario where msg.sender
        // seen by C is the forwarder but the tx originates from the owner, we have the owner call the forwarder which then
        // invokes C.burn. That keeps onlyOwner satisfied while msg.sender inside C is the forwarder.
        vm.prank(address(this));
        f.callBurn(amount);

        // record totalSupply after
        uint256 after = c.totalSupply();

        // The general invariant: totalSupply must decrease exactly by the burned amount
        // i.e., after == before - amount
        assertTrue(after == before - amount);
    }
}

// Forwarder contract: receives a call from the owner and forwards a call to C.burn(amount).
contract Forwarder {
    C c;
    constructor(address _c) {
        c = C(_c);
    }
    function callBurn(uint256 amount) external {
        // external caller (owner) triggers this; inside c, msg.sender will be address(this) (the forwarder)
        c.burn(amount);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: owner (msg.sender of deployer) must call burn.
    // We take burnAmount and require preconditions, then call burn and check totalSupply change.
    function check_burn(uint256 burnAmount) public {
        // require a meaningful burn amount
        require(burnAmount > 0, "burnAmount must be > 0");

        // Read pre-state
        uint256 before = c.totalSupply();
        uint256 ownerBalance = c.balanceOf(address(this));

        // To ensure the call will succeed on the original contract P, this test assumes
        // the InvMutTest contract is the owner of c. The verifier will supply such a c.
        // Ensure enough balance to burn
        require(ownerBalance >= burnAmount, "insufficient owner balance to burn");

        // Perform the state-changing call that distinguishes P from M
        bool ok = c.burn(burnAmount);
        // burn returns bool in P and M; ensure it didn't revert
        require(ok, "burn failed");

        // Read post-state and assert the invariant: totalSupply decreased exactly by burnAmount
        uint256 after = c.totalSupply();
        assert(after + burnAmount == before);
    }

    // Allow receiving ether (not used but harmless)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address ownerAddr, uint256 v) public payable {
        // precondition: caller must be owner and have at least v balance
        require(c.owner() == ownerAddr && c.balanceOf(ownerAddr) >= v);
        // perform burn as the owner by impersonating ownerAddr is not possible here,
        // so we instead require that the test contract is the owner and has balance
        // to perform the call. Enforce that by requiring c.owner() == address(this).
        require(c.owner() == address(this));
        // Now call burn; this changes totalSupply and balanceOf(address(this)).
        c.burn(v);
        // General invariant: totalSupply equals the sum of all balances.
        // We can observe totalSupply and this owner's balance; for ERC-like token
        // where only owner held tokens initially, sum of balances equals balanceOf(owner) + (totalSupply - balanceOf(owner))
        // But we can express invariant that totalSupply >= balanceOf(owner) and the difference equals sum of others, which is nonnegative.
        // Simpler observable rule that holds for original but breaks for mutant: after burn, totalSupply == c.balanceOf(address(this)) + (c.totalSupply() - c.balanceOf(address(this)))
        // That is tautological, so instead assert totalSupply >= balanceOf(owner) (owner's balance <= totalSupply) which fails when totalSupply underflows to 0 while balance remained large.
        assert(c.totalSupply() >= c.balanceOf(address(this)));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 burnAmount) public payable {
        // precondition: caller must be the owner and must have enough balance to burn
        // We require that msg.sender is owner by calling c.owner() and also require balance
        address owner = c.owner();
        require(owner == msg.sender);
        uint256 beforeOwnerBalance = c.balanceOf(owner);
        require(beforeOwnerBalance >= burnAmount);
        uint256 beforeTotal = c.totalSupply();

        // perform the state-changing call
        c.burn(burnAmount);

        // read afterwards
        uint256 afterOwnerBalance = c.balanceOf(owner);
        uint256 afterTotal = c.totalSupply();

        // General invariant: the decrease in owner's balance equals the decrease in totalSupply
        // i.e., (beforeOwnerBalance - afterOwnerBalance) == (beforeTotal - afterTotal)
        assert((beforeOwnerBalance - afterOwnerBalance) == (beforeTotal - afterTotal));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // precondition: caller must be the owner and have at least v balance
        // The contract C exposes owner via public variable 'owner' and balances via balanceOf
        require(msg.sender == c.owner());
        require(c.balanceOf(msg.sender) >= v);
        uint256 before = c.totalSupply();
        c.burn(v);
        uint256 after = c.totalSupply();
        // General rule: after a successful burn(v) by owner, totalSupply decreases exactly by v
        assert(after + v == before);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public payable {
        // precondition: this test must be run by the owner and owner must have at least v
        require(msg.sender == c.owner());
        require(c.balanceOf(msg.sender) >= v);

        // perform the burn call as in the counterexample
        c.burn(v);

        // Observe: totalSupply after burn plus owner's balance after burn equals sum of all balances.
        // Since we can only observe balances individually via balanceOf, compute sum by sampling a few addresses is impossible.
        // But note the invariant in this contract: totalSupply equals sum of all balances (because balances are the only holders of tokens)
        // Therefore after a burn by owner, totalSupply should equal the sum of all balances; equivalently, totalSupply + owner's balance == owner's balance + sum of others -> simplifies to totalSupply == sum of all balances.
        // To express a check that distinguishes double-subtraction mutant, we can verify that totalSupply is equal to owner's balance plus the sum of balances of zero-address and owner (using only public getters). Since we cannot enumerate all addresses, use the identity that before burn totalSupply == c.balanceOf(msg.sender) + (c.totalSupply() - c.balanceOf(msg.sender)) and after burn this must still hold.
        // A simpler computable invariant: For this contract, the owner's post-burn balance equals previous owner's balance minus v, and totalSupply equals previous totalSupply minus v. So totalSupply - c.totalSupply() == 0 would be constant — but we cannot access previous values. Instead we exploit that owner's post-burn balance equals c.balanceOf(msg.sender) and that mintToken only changes both sides similarly; ultimately the mutant causes totalSupply to decrease by an extra v, so totalSupply + c.balanceOf(msg.sender) should equal previous totalSupply + previous balance - 2*v vs original - v. To avoid needing previous values, we assert that totalSupply is at least equal to c.balanceOf(msg.sender) (since totalSupply is sum of all balances, and owner's balance is one part), which holds for the original but the mutant may make totalSupply less than owner's balance when totalSupply underflows to smaller value. Thus we assert totalSupply >= owner's balance.

        uint256 ts = c.totalSupply();
        uint256 ownerBal = c.balanceOf(msg.sender);
        assert(ts >= ownerBal);
    }
    receive() external payable { }
}

