pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzz the burn amount; the owner is the deployer (address(this) in setUp)
    function testFuzz_property(uint256 burnAmount) public {
        // keep burnAmount within a wide admissible domain but allow zero
        uint256 initialSupply = 1e18; // large enough supply
        // re-deploy a fresh contract with a known initial supply so balances are adequate
        c = new C(initialSupply, "T", "T");

        // owner is address(this) because setUp / deployment happens in this test context
        address owner = address(this);
        // bound burnAmount to [0, balance] to keep require(balance >= _value) satisfied
        uint256 maxBal = c.balanceOf(owner);
        burnAmount = bound(burnAmount, 0, maxBal);

        uint256 beforeTotal = c.totalSupply();

        // call burn as owner (we are already the owner/prank unnecessary)
        bool ok;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted, then it violated the precondition; with our bounding it should not revert
        // We still allow the path where burn(0) may succeed trivially. Read totalSupply after.
        uint256 afterTotal = c.totalSupply();

        // The universal property: after a successful burn(amount) the totalSupply decreased exactly by amount.
        // We assert that when burn returned (ok == true), afterTotal == beforeTotal - burnAmount.
        // This holds for the reference contract for all admissible inputs; the mutant that subtracts twice
        // will make this fail for some burnAmount > 0.
        if (ok) {
            assertTrue(afterTotal == beforeTotal - burnAmount);
        } else {
            // If burn reverted despite our bounds, fail the test (shouldn't happen for reference)
            assertTrue(false);
        }
    }
