import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }

    // fuzzed: amount to burn and an address that will be the caller
    function testFuzz_property(uint256 burnAmt, address caller) public {
        // keep caller non-zero and distinct-ish; allow fuzzer wide domain
        vm.assume(caller != address(0));

        // give caller some balance by minting tokens to them as owner (setUp deployer is owner)
        // ensure owner (address(this)) has enough initial tokens: contract was deployed with 0 supply,
        // so mint some to owner and then transfer to caller
        uint256 seedMint = bound(burnAmt + 1, 1, type(uint256).max/2);
        // mint to this (owner)
        c.mintToken(address(this), seedMint + 1);
        // transfer some to caller so caller can have at least burnAmt (if burnAmt==0 it's fine)
        uint256 give = burnAmt;
        // bound give so not overflow in practice
        give = bound(give, 0, seedMint);
        // transfer from owner to caller
        if (give > 0) {
            c.transfer(caller, give);
        }

        // Record balances and totalSupply before
        uint256 beforeCallerBal = c.balanceOf(caller);
        uint256 beforeTotal = c.totalSupply();

        // run burn as the caller if caller==owner then direct, else impersonate caller
        // Only owner can call burn; if caller is not owner the call will revert — that's admissible but
        // we want the property to hold for any admissible inputs: the invariant concerns calls that succeed.
        // So we restrict to caller == owner to exercise successful burn paths while still fuzzing burnAmt.
        vm.assume(caller == address(this));

        // Now call burn and observe success; use try/catch to capture revert differences if any
        bool ok;
        try c.burn(burnAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted then the preconditions weren't met (burn > balance) — in the reference contract
        // that would revert; then the invariant about equal decrease is vacuously preserved because state unchanged.
        // We only assert the invariant when the call succeeded (ok==true).
        if (ok) {
            // exactly one assertion: in the correct contract, when burn succeeds it reduces caller balance
            // and reduces totalSupply by the same amount, so beforeCallerBal - c.balanceOf(caller) == beforeTotal - c.totalSupply()
            // Rearranged: c.balanceOf(caller) + c.totalSupply() == beforeCallerBal + beforeTotal
            assertTrue(c.balanceOf(caller) + c.totalSupply() == beforeCallerBal + beforeTotal);
        } else {
            // If call reverted, then the reference contract also reverts for the same inputs (we are owner),
            // so we assert that state remained unchanged (burn didn't happen). This also holds for reference.
            assertTrue(c.balanceOf(caller) == beforeCallerBal && c.totalSupply() == beforeTotal);
        }
    }
}

